/// @nodoc
class ResourceStatus {
  static const available = ResourceStatus._('AVAILABLE');
  static const failed = ResourceStatus._('FAILED');
  static const provisioning = ResourceStatus._('PROVISIONING');
  static const terminated = ResourceStatus._('TERMINATED');
  static const terminating = ResourceStatus._('TERMINATING');
  static const updating = ResourceStatus._('UPDATING');
  static const maintenanceInProgress =
      ResourceStatus._('MAINTENANCE_IN_PROGRESS');

  final String value;

  const ResourceStatus._(this.value);

  static const values = [
    available,
    failed,
    provisioning,
    terminated,
    terminating,
    updating,
    maintenanceInProgress
  ];

  static ResourceStatus fromString(String value) =>
      values.firstWhere((e) => e.value == value,
          orElse: () => ResourceStatus._(value));

  @override
  bool operator ==(other) => other is ResourceStatus && other.value == value;

  @override
  int get hashCode => value.hashCode;

  @override
  String toString() => value;
}

