/// @nodoc
class ManagedResourceStatus {
  static const enabled = ManagedResourceStatus._('ENABLED');
  static const enabling = ManagedResourceStatus._('ENABLING');
  static const disabled = ManagedResourceStatus._('DISABLED');
  static const disabling = ManagedResourceStatus._('DISABLING');

  final String value;

  const ManagedResourceStatus._(this.value);

  static const values = [enabled, enabling, disabled, disabling];

  static ManagedResourceStatus fromString(String value) =>
      values.firstWhere((e) => e.value == value,
          orElse: () => ManagedResourceStatus._(value));

  @override
  bool operator ==(other) =>
      other is ManagedResourceStatus && other.value == value;

  @override
  int get hashCode => value.hashCode;

  @override
  String toString() => value;
}

