  /// The status of the patching operation. Possible values are
  /// <code>SCHEDULED</code>, <code>MAINTENANCE_IN_PROGRESS</code>,
  /// <code>FAILED</code>, and <code>COMPLETE</code>.
  final DbServerPatchingStatus? patchingStatus;

  /// The time when the patching operation ended.
  final String? timePatchingEnded;

  /// The time when the patching operation started.
  final String? timePatchingStarted;

