/// @nodoc
class DbServerPatchingStatus {
  static const complete = DbServerPatchingStatus._('COMPLETE');
  static const failed = DbServerPatchingStatus._('FAILED');
  static const maintenanceInProgress =
      DbServerPatchingStatus._('MAINTENANCE_IN_PROGRESS');
  static const scheduled = DbServerPatchingStatus._('SCHEDULED');

  final String value;

  const DbServerPatchingStatus._(this.value);

  static const values = [complete, failed, maintenanceInProgress, scheduled];

  static DbServerPatchingStatus fromString(String value) =>
      values.firstWhere((e) => e.value == value,
          orElse: () => DbServerPatchingStatus._(value));

  @override
  bool operator ==(other) =>
      other is DbServerPatchingStatus && other.value == value;

  @override
  int get hashCode => value.hashCode;

  @override
  String toString() => value;
}

