/// The scheduling details for the maintenance window. Patching and system
/// updates take place during the maintenance window.
///
/// @nodoc
class MaintenanceWindow {
  /// The custom action timeout in minutes for the maintenance window.
  final int? customActionTimeoutInMins;

  /// The days of the week when maintenance can be performed.
  final List<DayOfWeek>? daysOfWeek;

  /// The hours of the day when maintenance can be performed.
  final List<int>? hoursOfDay;

  /// Indicates whether custom action timeout is enabled for the maintenance
  /// window.
  final bool? isCustomActionTimeoutEnabled;

  /// The lead time in weeks before the maintenance window.
  final int? leadTimeInWeeks;

  /// The months when maintenance can be performed.
  final List<Month>? months;

  /// The patching mode for the maintenance window.
  final PatchingModeType? patchingMode;

  /// The preference for the maintenance window scheduling.
  final PreferenceType? preference;

  /// Indicates whether to skip release updates during maintenance.
  final bool? skipRu;

  /// The weeks of the month when maintenance can be performed.
  final List<int>? weeksOfMonth;

  MaintenanceWindow({
    this.customActionTimeoutInMins,
    this.daysOfWeek,
    this.hoursOfDay,
    this.isCustomActionTimeoutEnabled,
    this.leadTimeInWeeks,
    this.months,
    this.patchingMode,
    this.preference,
    this.skipRu,
    this.weeksOfMonth,
  });

  factory MaintenanceWindow.fromJson(Map<String, dynamic> json) {
    return MaintenanceWindow(
      customActionTimeoutInMins: json['customActionTimeoutInMins'] as int?,
      daysOfWeek: (json['daysOfWeek'] as List?)
          ?.nonNulls
          .map((e) => DayOfWeek.fromJson(e as Map<String, dynamic>))
          .toList(),
      hoursOfDay:
          (json['hoursOfDay'] as List?)?.nonNulls.map((e) => e as int).toList(),
      isCustomActionTimeoutEnabled:
          json['isCustomActionTimeoutEnabled'] as bool?,
      leadTimeInWeeks: json['leadTimeInWeeks'] as int?,
      months: (json['months'] as List?)
          ?.nonNulls
          .map((e) => Month.fromJson(e as Map<String, dynamic>))
          .toList(),
      patchingMode:
          (json['patchingMode'] as String?)?.let(PatchingModeType.fromString),
      preference:
          (json['preference'] as String?)?.let(PreferenceType.fromString),
      skipRu: json['skipRu'] as bool?,
      weeksOfMonth: (json['weeksOfMonth'] as List?)
          ?.nonNulls
          .map((e) => e as int)
          .toList(),
    );
  }

  Map<String, dynamic> toJson() {
    final customActionTimeoutInMins = this.customActionTimeoutInMins;
    final daysOfWeek = this.daysOfWeek;
    final hoursOfDay = this.hoursOfDay;
    final isCustomActionTimeoutEnabled = this.isCustomActionTimeoutEnabled;
    final leadTimeInWeeks = this.leadTimeInWeeks;
    final months = this.months;
    final patchingMode = this.patchingMode;
    final preference = this.preference;
    final skipRu = this.skipRu;
    final weeksOfMonth = this.weeksOfMonth;
    return {
      if (customActionTimeoutInMins != null)
        'customActionTimeoutInMins': customActionTimeoutInMins,
      if (daysOfWeek != null) 'daysOfWeek': daysOfWeek,
      if (hoursOfDay != null) 'hoursOfDay': hoursOfDay,
      if (isCustomActionTimeoutEnabled != null)
        'isCustomActionTimeoutEnabled': isCustomActionTimeoutEnabled,
      if (leadTimeInWeeks != null) 'leadTimeInWeeks': leadTimeInWeeks,
      if (months != null) 'months': months,
      if (patchingMode != null) 'patchingMode': patchingMode.value,
      if (preference != null) 'preference': preference.value,
      if (skipRu != null) 'skipRu': skipRu,
      if (weeksOfMonth != null) 'weeksOfMonth': weeksOfMonth,
    };
  }
