  /// The HTTPS link to the Exadata infrastructure in OCI.
  final String? ociUrl;

  /// The OCID of the Exadata infrastructure.
  final String? ocid;

  /// The amount of progress made on the current operation on the Exadata
  /// infrastructure, expressed as a percentage.
