/// A summary of an Autonomous Virtual Machine (VM) within an Autonomous VM
/// cluster.
///
/// @nodoc
class AutonomousVirtualMachineSummary {
  /// The unique identifier of the Autonomous VM.
  final String? autonomousVirtualMachineId;

