  /// The number of CPU cores allocated to this Autonomous VM.
  final int? cpuCoreCount;

  /// The amount of storage allocated to this Autonomous Virtual Machine, in
  /// gigabytes (GB).
  final int? dbNodeStorageSizeInGBs;

  /// The display name of the database server hosting this Autonomous VM.
  final String? dbServerDisplayName;

  /// The unique identifier of the database server hosting this Autonomous VM.
  final String? dbServerId;

  /// The amount of memory allocated to this Autonomous VM, in gigabytes (GB).
  final int? memorySizeInGBs;

  /// The name of the Oracle Cloud Infrastructure (OCI) resource anchor associated
  /// with this Autonomous VM.
  final String? ociResourceAnchorName;

  /// The Oracle Cloud Identifier (OCID) of the Autonomous VM.
  final String? ocid;

  /// The current status of the Autonomous VM.
  final ResourceStatus? status;

  /// Additional information about the current status of the Autonomous VM, if
  /// applicable.
  final String? statusReason;

  /// The name of the Autonomous VM.
  final String? vmName;

  AutonomousVirtualMachineSummary({
    this.autonomousVirtualMachineId,
    this.clientIpAddress,
    this.cloudAutonomousVmClusterId,
    this.cpuCoreCount,
    this.dbNodeStorageSizeInGBs,
    this.dbServerDisplayName,
    this.dbServerId,
    this.memorySizeInGBs,
    this.ociResourceAnchorName,
    this.ocid,
    this.status,
    this.statusReason,
    this.vmName,
  });

  factory AutonomousVirtualMachineSummary.fromJson(Map<String, dynamic> json) {
    return AutonomousVirtualMachineSummary(
      autonomousVirtualMachineId: json['autonomousVirtualMachineId'] as String?,
      clientIpAddress: json['clientIpAddress'] as String?,
      cloudAutonomousVmClusterId: json['cloudAutonomousVmClusterId'] as String?,
      cpuCoreCount: json['cpuCoreCount'] as int?,
